using System;using System.IO;using System.Text;using System.Linq;using System.Diagnostics;using System.Runtime.InteropServices;using System.Windows.Automation;using System.Web.Script.Serialization;
class PrivatePrint105 {
 delegate bool EnumProc(IntPtr h,IntPtr l);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumProc p,IntPtr l);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint p);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder b,int n);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr h,StringBuilder b,int n);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("kernel32.dll")]static extern uint GetCurrentThreadId();[DllImport("user32.dll")]static extern IntPtr GetThreadDesktop(uint t);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetUserObjectInformation(IntPtr h,int kind,StringBuilder b,int n,out int need);
 [DllImport("user32.dll",CharSet=CharSet.Unicode,EntryPoint="SendMessageW")]static extern IntPtr SendText(IntPtr h,uint m,IntPtr w,string text);
 static string Text(IntPtr h,bool cls=false){var b=new StringBuilder(1024);if(cls)GetClassName(h,b,b.Capacity);else GetWindowText(h,b,b.Capacity);return b.ToString();}
 [STAThread]static int Main(string[] a){try{var b=new StringBuilder(256);int need;GetUserObjectInformation(GetThreadDesktop(GetCurrentThreadId()),2,b,512,out need);if(b.ToString()!="CodeAssistVerify-runtime")throw new Exception("Private desktop required");int pid=int.Parse(a[0]);if(Process.GetProcessById(pid).ProcessName!="devenv")throw new Exception("Expected VS");if(a.Length==3){string pdf=Path.GetFullPath(a[2]);if(!pdf.StartsWith("C:\\Projects\\CodeAssist\\.local\\parity-runs\\background-103\\",StringComparison.OrdinalIgnoreCase)||Path.GetExtension(pdf)!=".pdf"||File.Exists(pdf)||!Directory.Exists(Path.GetDirectoryName(pdf)))throw new Exception("Owned new PDF path required");IntPtr save=IntPtr.Zero;EnumWindows((h,l)=>{uint sp;GetWindowThreadProcessId(h,out sp);if(sp==pid&&IsWindowVisible(h)&&Text(h,true)=="#32770"&&Text(h)=="다음 이름으로 프린터 출력 저장"){if(save!=IntPtr.Zero)throw new Exception("Ambiguous PDF save dialog");save=h;}return true;},IntPtr.Zero);if(save==IntPtr.Zero)throw new Exception("Observed PDF save dialog missing");var saveRoot=AutomationElement.FromHandle(save);var field=saveRoot.FindAll(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Edit),new PropertyCondition(AutomationElement.AutomationIdProperty,"1001"))).Cast<AutomationElement>().Single();var fieldHandle=(IntPtr)field.Current.NativeWindowHandle;uint fp;GetWindowThreadProcessId(fieldHandle,out fp);if(fp!=pid)throw new Exception("Unowned PDF field");SendText(fieldHandle,0xC,IntPtr.Zero,pdf);if(((ValuePattern)field.GetCurrentPattern(ValuePattern.Pattern)).Current.Value!=pdf)throw new Exception("PDF field not applied");var saveButton=saveRoot.FindAll(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Button),new PropertyCondition(AutomationElement.AutomationIdProperty,"1"))).Cast<AutomationElement>().Single();PostMessage((IntPtr)saveButton.Current.NativeWindowHandle,0xF5,IntPtr.Zero,IntPtr.Zero);File.WriteAllText(a[1],new JavaScriptSerializer().Serialize(new{pid,desktop=b.ToString(),pdf,saveRequested=true}));return 0;}IntPtr dialog=IntPtr.Zero;EnumWindows((h,l)=>{uint p;GetWindowThreadProcessId(h,out p);if(p==pid&&IsWindowVisible(h)&&Text(h,true)=="#32770"&&Text(h)=="인쇄"){if(dialog!=IntPtr.Zero)throw new Exception("Ambiguous print dialog");dialog=h;}return true;},IntPtr.Zero);if(dialog==IntPtr.Zero)throw new Exception("Print dialog absent");var root=AutomationElement.FromHandle(dialog);var entries=root.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.ListItem)).Cast<AutomationElement>().Where(x=>x.Current.Name=="Microsoft Print to PDF").ToArray();if(entries.Length!=1||!((SelectionItemPattern)entries[0].GetCurrentPattern(SelectionItemPattern.Pattern)).Current.IsSelected)throw new Exception("Microsoft Print to PDF must already be selected");var buttons=root.FindAll(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Button),new PropertyCondition(AutomationElement.AutomationIdProperty,"1"))).Cast<AutomationElement>().ToArray();if(buttons.Length!=1)throw new Exception("Ambiguous print button");var button=(IntPtr)buttons[0].Current.NativeWindowHandle;uint bp;GetWindowThreadProcessId(button,out bp);if(bp!=pid||!buttons[0].Current.IsEnabled)throw new Exception("Invalid print control");if(!PostMessage(button,0xF5,IntPtr.Zero,IntPtr.Zero))throw new Exception("Print click failed");File.WriteAllText(a[1],new JavaScriptSerializer().Serialize(new{pid,desktop=b.ToString(),printer="Microsoft Print to PDF",dialog=dialog.ToInt64(),button=button.ToInt64(),virtualPrintRequested=true}));return 0;}catch(Exception e){File.WriteAllText(a[1],new JavaScriptSerializer().Serialize(new{error=e.ToString()}));return 1;}}
}
